787:     private function processGiftSpinWin(
788:         array $data,
789:         User $user,
790:         Wallet $wallet,
791:         string $transferId,
792:         string $roundNumber,
793:         $gameKey,
794:         string $sessionId,
795:         float $beforeAmount,
796:         int $rawAmountCoins,
797:         float $amount,
798:         int $time
799:     ): ?array {
800:         $freespin = $this->findGiftSpin($data, $user, $wallet->currency);
801:         if (!$freespin) {
802:             return null; // anomalous GIFT_SPIN — let the normal win path credit + log
803:         }
804: 
805:         // 1) progress (quantity_left / status / total_win), even for a losing spin
806:         FreespinProgressService::recordSpinProgress($freespin, $this->giftSpinRemaining($data), $amount);
807: 
808:         // Close a linked bonus-code campaign when spins are exhausted — parity with
809:         // SiteController's sync `userBonusCod->closeBonus()` (the async pipeline only
810:         // flags BonusCodLog.used).
811:         $userBonusCod = $freespin->userBonusCod;
812:         if ($userBonusCod && (int)$freespin->quantity_left === 0) {
813:             $userBonusCod->closeBonus();
814:         }
815: 
816:         // 2) credit routing — same predicate as SiteController's freespin-win branch.
817:         // The real/bonus split is computed by EgtWallet::giftSpinSplit and shared
818:         // with the idempotency replay so a retry reproduces the identical response.
819:         $creditRealSync = $this->giftSpinCreditsReal($freespin);
820:         $split = EgtWallet::giftSpinSplit($creditRealSync, $rawAmountCoins);
821: 
822:         if ($creditRealSync && $amount > 0) {
823:             Yii::$app->db->createCommand(
824:                 'UPDATE wallet SET amount = amount + :amount WHERE id = :id',
825:                 [':amount' => $amount, ':id' => $wallet->id]
826:             )->execute();
827:             $wallet->amount = $wallet->amount + $amount;
828:         }
829: 
830:         // 3) ledger record (idempotency key = transferId) tagged as a freespin win

